CREATE TABLE "StickerPack" ("id" TEXT NOT NULL,"slug" TEXT NOT NULL,"title" TEXT NOT NULL,"description" TEXT NOT NULL DEFAULT '',"active" BOOLEAN NOT NULL DEFAULT true,CONSTRAINT "StickerPack_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "StickerPack_slug_key" ON "StickerPack"("slug");
CREATE TABLE "Sticker" ("id" TEXT NOT NULL,"packId" TEXT NOT NULL,"number" INTEGER NOT NULL,"title" TEXT NOT NULL,"emoji" TEXT NOT NULL,"rarity" TEXT NOT NULL DEFAULT 'COMMON',"active" BOOLEAN NOT NULL DEFAULT true,CONSTRAINT "Sticker_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "Sticker_packId_number_key" ON "Sticker"("packId","number");
ALTER TABLE "Sticker" ADD CONSTRAINT "Sticker_packId_fkey" FOREIGN KEY ("packId") REFERENCES "StickerPack"("id") ON DELETE CASCADE ON UPDATE CASCADE;
CREATE TABLE "StickerInventory" ("userId" TEXT NOT NULL,"stickerId" TEXT NOT NULL,"quantity" INTEGER NOT NULL DEFAULT 0,CONSTRAINT "StickerInventory_pkey" PRIMARY KEY ("userId","stickerId"),CONSTRAINT "StickerInventory_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE,CONSTRAINT "StickerInventory_stickerId_fkey" FOREIGN KEY ("stickerId") REFERENCES "Sticker"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE INDEX "StickerInventory_stickerId_idx" ON "StickerInventory"("stickerId");
CREATE TABLE "StickerGrant" ("id" TEXT NOT NULL,"userId" TEXT NOT NULL,"stickerId" TEXT NOT NULL,"quantity" INTEGER NOT NULL,"reason" TEXT NOT NULL DEFAULT '',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "StickerGrant_pkey" PRIMARY KEY ("id"),CONSTRAINT "StickerGrant_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE,CONSTRAINT "StickerGrant_stickerId_fkey" FOREIGN KEY ("stickerId") REFERENCES "Sticker"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE INDEX "StickerGrant_userId_createdAt_idx" ON "StickerGrant"("userId","createdAt");
